{
  "id": "p_002",
  "summary": "Minimalist REST API design for task management, defining CRUD endpoints, JSON schemas, and standard error structures without implementation code.",
  "approach": "Define a standard RESTful resource `/tasks` with HTTP methods mapping to CRUD operations. Use JSON Schema conventions within the design document to specify payload structures. Standardize error responses using a consistent envelope.",
  "tradeoffs": [
    "Using UUIDs for IDs prevents enumeration but requires client-side generation or specific DB support.",
    "Omitting pagination simplifies the API but limits scalability for large task lists.",
    "Using PUT instead of PATCH requires clients to send the full resource representation for updates."
  ],
  "evidence": [
    "REST principles dictate mapping CRUD to POST, GET, PUT, DELETE on noun-based routes.",
    "JSON Schema is the standard for defining JSON payload structures in OpenAPI/Swagger."
  ],
  "artifacts": [
    {
      "kind": "api-design.ts",
      "language": "typescript",
      "source": "export const apiDesign = {
  "endpoints": [
    {
      "method": "POST",
      "route": "/tasks",
      "request_schema": {
        "type": "object",
        "required": ["title"],
        "properties": {
          "title": { "type": "string" },
          "description": { "type": "string" },
          "status": { "type": "string", "enum": ["pending", "in_progress", "done"], "default": "pending" }
        }
      },
      "response_schema": { "$ref": "#/definitions/Task" }
    },
    {
      "method": "GET",
      "route": "/tasks",
      "request_schema": null,
      "response_schema": { "type": "array", "items": { "$ref": "#/definitions/Task" } }
    },
    {
      "method": "GET",
      "route": "/tasks/{id}",
      "request_schema": { "type": "object", "properties": { "id": { "type": "string", "format": "uuid" } }, "required": ["id"] },
      "response_schema": { "$ref": "#/definitions/Task" }
    },
    {
      "method": "PUT",
      "route": "/tasks/{id}",
      "request_schema": {
        "type": "object",
        "required": ["title", "status"],
        "properties": {
          "title": { "type": "string" },
          "description": { "type": "string" },
          "status": { "type": "string", "enum": ["pending", "in_progress", "done"] }
        }
      },
      "response_schema": { "$ref": "#/definitions/Task" }
    },
    {
      "method": "DELETE",
      "route": "/tasks/{id}",
      "request_schema": { "type": "object", "properties": { "id": { "type": "string", "format": "uuid" } }, "required": ["id"] },
      "response_schema": { "type": "object", "properties": { "message": { "type": "string" } } }
    }
  ],
  "definitions": {
    "Task": {
      "type": "object",
      "properties": {
        "id": { "type": "string", "format": "uuid" },
        "title": { "type": "string" },
        "description": { "type": "string" },
        "status": { "type": "string", "enum": ["pending", "in_progress", "done"] },
        "created_at": { "type": "string", "format": "date-time" }
      }
    }
  },
  "error_schema": {
    "type": "object",
    "properties": {
      "error": {
        "type": "object",
        "required": ["code", "message"],
        "properties": {
          "code": { "type": "string" },
          "message": { "type": "string" },
          "details": { "type": "array", "items": { "type": "object", "properties": { "field": { "type": "string" }, "issue": { "type": "string" } } } }
        }
      }
    }
  }
};"
    }
  ]
}
